class Solution {
    private static final long MOD=1000000007;
    private long power(long base,int exponent){
        long answer=1;
        while(exponent-->0)answer=answer*base%MOD;
        return answer;
    }
    private long combination(int n,int r){
        r=Math.min(r,n-r);
        long answer=1;
        for(int i=1;i<=r;i++)answer=answer*(n-r+i)/i;
        return answer;
    }
    public int countKSubsequencesWithMaxBeauty(String s,int k){
        int[] frequency=new int[26];
        for(char ch:s.toCharArray())frequency[ch-'a']++;
        List<Integer> values=new ArrayList<>();
        for(int value:frequency)if(value>0)values.add(value);
        values.sort(Collections.reverseOrder());
        if(values.size()<k)return 0;
        int threshold=values.get(k-1),greater=0,equal=0;
        long answer=1;
        for(int value:frequency)if(value>threshold){
            answer=answer*value%MOD;
            greater++;
        }else if(value==threshold)equal++;
        int needed=k-greater;
        answer=answer*power(threshold,needed)%MOD;
        answer=answer*(combination(equal,needed)%MOD)%MOD;
        return (int)answer;
    }
}

